import re

# GSM8K answers are a single number. Match a full numeric token so commas inside
# thousands ("18,000") and decimals stay attached, while a trailing period does not.
_NUMBER_RE = re.compile(r"-?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?")


def _normalize_number(text):
    return text.replace(",", "").replace("$", "")


def _numbers_equal(predicted, ground_truth):
    """Numeric equality. '18', '18.0', and '18.00' match; a missing answer does not."""
    if predicted is None or ground_truth is None:
        return False
    pred = _normalize_number(str(predicted)).strip()
    gold = _normalize_number(str(ground_truth)).strip()
    if pred == gold:
        return True
    try:
        return abs(float(pred) - float(gold)) <= 1e-6
    except ValueError:
        return False


def extract_solution(solution_str, method="strict"):
    assert method in ["strict", "flexible"]

    # Grade the whole solution. A tail clip drops a correct #### / final number when
    # the response continues past it (explanations, a second attempt, EOS chatter).
    if method == "strict":
        # this also tests the formatting of the model
        solutions = re.findall(r"####\s*(" + _NUMBER_RE.pattern + r")", solution_str)
        if len(solutions) == 0:
            final_answer = None
        else:
            # take the last solution
            final_answer = _normalize_number(solutions[-1])
    elif method == "flexible":
        # Qwen-style GSM8K answers usually put the final number at the end
        # ("Therefore, ... is 18.") or inside \boxed{18}, and often omit "####".
        # Prefer an explicit #### answer; otherwise use the last numeric token.
        solutions = re.findall(r"####\s*(" + _NUMBER_RE.pattern + r")", solution_str)
        if solutions:
            final_answer = _normalize_number(solutions[-1])
        else:
            answer = _NUMBER_RE.findall(solution_str)
            final_answer = _normalize_number(answer[-1]) if answer else None
    return final_answer


def compute_score(solution_str, ground_truth, method="flexible", format_score=0.0, score=1.0):
    """The scoring function for GSM8k.

    Reference: Trung, Luong, et al. "Reft: Reasoning with reinforced fine-tuning." Proceedings of the 62nd Annual
    Meeting of the Association for Computational Linguistics (Volume 1: Long Papers). 2024.

    Args:
        solution_str: the solution text
        ground_truth: the ground truth
        method: the method to extract the solution, choices are 'strict' and 'flexible'
        format_score: the score for the format
        score: the score for the correct answer
    """
    answer = extract_solution(solution_str=solution_str, method=method)
    if answer is None:
        return 0
    else:
        if _numbers_equal(answer, ground_truth):
            return score
        else:
            return format_score

