def extract_solution(solution_str, method="strict"):
    assert method in ["strict", "flexible"]

    # Always search the full string. The answer is usually at the end, but a
    # correct "#### <number>" can sit before a short continuation, and a fixed
    # 300-character tail clip drops it.
    hash_answers = re.findall(r"####\s*(" + _NUMBER_RE.pattern + r")", solution_str)
    if method == "strict" or hash_answers:
        # The held-out grader uses the last "#### <number>". When that tag is
        # present, training must use the same answer so the reward matches it.
        if not hash_answers:
            return None
        return _normalize_number(hash_answers[-1])

    # Qwen often answers with \boxed{18} or a sentence-final number and never
    # emits "####". Credit those, using the last number in the response.
    boxed = re.findall(r"\\boxed\{([^{}]*)\}", solution_str)
    if boxed:
        nums = _NUMBER_RE.findall(boxed[-1])
        if nums:
            return _normalize_number(nums[-1])
    nums = _NUMBER_RE.findall(solution_str)
    if not nums:
        return None
    return _normalize_number(nums[-1])
